//! Actual unmodified original history checks on public synthetic data.
//! The original fixed194 forecasts and actual observations are preserved.
//! Structural later-state events do not establish chain or execution authority.
use semantica_runtime::{refinery_contracts as wire, refinery_history as history};
use serde_json::Value;

fn original() -> Value {
    assert_eq!(
        semantica_runtime::sha256(ORIGINAL_HISTORY_JSON),
        ORIGINAL_PROJECTION_SHA256
    );
    let value = semantica_json::strict_json(ORIGINAL_HISTORY_JSON.as_bytes()).unwrap();
    assert_eq!(
        value["original_inputs_sha256"],
        "eed00484b48ac70deb4a2c3edf80c5147f39635f822fa8ef71ada58f9578bf9c"
    );
    assert_eq!(
        value["original_receipt_sha256"],
        "cb92307f8123bcd20c1aae87598ea9bdc2922a4dfc433dbb751ca8ec31c44ff5"
    );
    assert_eq!(
        value["source_sha256"],
        "6a7d70ae69f2720a85414db2b7ee05787699a1d93271699276aae5908cd94594"
    );
    assert_eq!(value["cases"].as_array().unwrap().len(), 194);
    for row in value["cases"].as_array().unwrap() {
        assert_eq!(
            row["original_forecast_accepted"], row["observed"]["accepted"],
            "fixed independent forecast matches actual original:{}",
            row["id"]
        );
        assert_eq!(row["observed"]["forecast_matched"], true);
    }
    value
}

#[test]
fn original_workspace_read_domain_and_existing_owner_binding_are_distinct() {
    let fixture = original();
    let rows = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|row| row["kind"] == "workspace")
        .collect::<Vec<_>>();
    assert_eq!(rows.len(), 16);
    for row in rows {
        let originally_valid = row["observed"]["accepted"].as_bool().unwrap();
        let original_registry = row["input"]["registry_id"].as_str().unwrap_or("registry-1");
        if originally_valid {
            // Original _read_workspace checks opaque ID, not owner matching.
            assert!(
                history::workspace(&row["input"], original_registry).is_ok(),
                "original workspace data:{}",
                row["id"]
            );
            assert_eq!(row["observed"]["result"], row["input"]);
        }
        let expected_bound =
            originally_valid && row["input"]["registry_id"] == row["registry_id_expected"];
        assert_eq!(
            history::workspace(&row["input"], row["registry_id_expected"].as_str().unwrap())
                .is_ok(),
            expected_bound,
            "same-owner workspace binding:{}",
            row["id"]
        );
    }
}

#[test]
fn original_pointer_domain_is_separate_from_strict_event_chain() {
    let fixture = original();
    let rows = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|row| row["kind"] == "pointer")
        .collect::<Vec<_>>();
    assert_eq!(rows.len(), 38);
    for row in rows {
        assert_eq!(
            history::pointer(&row["input"]).is_ok(),
            row["observed"]["accepted"].as_bool().unwrap(),
            "original pointer data:{}",
            row["id"]
        );
    }
    let source_weak = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|row| {
            row["id"]
                .as_str()
                .unwrap()
                .starts_with("pointer-original-weak-sequence-")
        })
        .collect::<Vec<_>>();
    assert_eq!(source_weak.len(), 5);
    for row in source_weak {
        assert!(
            history::pointer(&row["input"]).is_ok(),
            "original accepts these values structurally; chain verifier has separate strict sequence checks"
        );
    }
    let absent = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["id"] == "pointer-candidate-two-nullable-absent")
        .unwrap();
    assert!(history::pointer(&absent["input"]).is_ok());
    assert!(absent["observed"]["result"]["previous_event_sha256"].is_null());
    assert!(absent["observed"]["result"]["package_sha256"].is_null());
}

#[test]
fn all_six_original_event_payloads_keep_fixed_source_checks_and_hashes() {
    let fixture = original();
    let rows = fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|row| row["kind"] == "event")
        .collect::<Vec<_>>();
    assert_eq!(rows.len(), 140);
    let valid_states = rows
        .iter()
        .filter(|row| row["id"].as_str().unwrap().starts_with("event-valid-"))
        .map(|row| row["input"]["state"].as_str().unwrap())
        .collect::<Vec<_>>();
    assert_eq!(valid_states, wire::STATES);
    for row in rows {
        assert_eq!(
            history::event(&row["input"]).is_ok(),
            row["observed"]["accepted"].as_bool().unwrap(),
            "actual original immutable event:{}",
            row["id"]
        );
    }
    // For all six states the unknown payload was freshly hashed by original
    // canonical_json; rejection therefore depends on the exact payload schema,
    // and cannot be satisfied by checking only that a supplied hash is stale.
    for row in fixture["cases"].as_array().unwrap().iter().filter(|row| {
        row["id"]
            .as_str()
            .unwrap()
            .starts_with("event-payload-extra-")
    }) {
        let mut content = row["input"].clone();
        content.as_object_mut().unwrap().remove("event_sha256");
        assert_eq!(
            wire::digest(&content).unwrap(),
            row["input"]["event_sha256"]
        );
        assert!(history::event(&row["input"]).is_err());
    }
}

